package com.ruoyi.warehouse.finance;

import com.ruoyi.warehouse.billing.*;
import com.ruoyi.warehouse.data.WarehouseRepository;
import com.ruoyi.warehouse.security.WarehouseScope;
import com.ruoyi.warehouse.support.*;
import java.math.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class FinanceWorkflowService {
    private final WarehouseRepository records;private final WarehouseScope scope;private final FinanceRuleService rules;private final JdbcTemplate jdbc;
    public FinanceWorkflowService(WarehouseRepository records,WarehouseScope scope,FinanceRuleService rules){this.records=records;this.scope=scope;this.rules=rules;this.jdbc=records.jdbc();}
    public Map<String,Object> list(String kind,int page,int size,String client){rules.permission("query");if(!Set.of("charges","invoices","billingRuns").contains(kind))throw WarehouseException.invalid("Unsupported finance list");
        // Client-owned invoices can span warehouses. Filter whole aggregates, never trim lines.
        var args=new ArrayList<Object>();args.add(kind);String where="r.kind=? AND "+scope.predicate(kind,args);if(client!=null&&!client.isBlank()){where+=" AND r.client_id=?";args.add(client);}
        if(page<1||size<1||size>200||page>100000)throw WarehouseException.invalid("Invalid pagination");
        if(!scope.admin()){args.add(scope.actor());where+=" AND NOT EXISTS (SELECT 1 FROM wh_reference x JOIN wh_record target ON target.id=x.target_id WHERE x.owner_id=r.id AND (CASE WHEN target.kind='warehouses' THEN target.id ELSE target.warehouse_id END)<>'' AND (CASE WHEN target.kind='warehouses' THEN target.id ELSE target.warehouse_id END) NOT IN (SELECT scope_id FROM wh_user_scope WHERE user_id=? AND scope_type='WAREHOUSE'))";}
        long total=jdbc.queryForObject("SELECT COUNT(*) FROM wh_record r WHERE "+where,Long.class,args.toArray());args.add(size);args.add((long)(page-1)*size);
        var ids=jdbc.queryForList("SELECT r.id FROM wh_record r WHERE "+where+" ORDER BY r.created_at DESC,r.id LIMIT ? OFFSET ?",String.class,args.toArray());var result=new ArrayList<Map<String,Object>>();for(String id:ids){var row=records.get(kind,id,false);assertAggregate(kind,row);result.add(row);}return Map.of("code",200,"msg","success","total",total,"rows",result);
    }
    public Map<String,Object> invoice(String id){rules.permission("query");var row=records.get("invoices",id,false);assertAggregate("invoices",row);return row;}
    public Map<String,Object> run(String id){rules.permission("query");var row=records.get("billingRuns",id,false);assertAggregate("billingRuns",row);return row;}
    void assertAggregate(String kind,Map<String,Object> row){scope.assertRecord(kind,row);if("billingRuns".equals(kind))for(var charge:WarehouseJson.maps(row.get("charges")))assertAggregate("charges",records.get("charges",WarehouseJson.text(charge,"id"),false));if("charges".equals(kind))for(Object oid:array(row.get("orderIds")))records.scoped("orders",String.valueOf(oid),false);
        for(Object wid:array(row.get("warehouseIds")))records.scoped("warehouses",String.valueOf(wid),false);
        if("invoices".equals(kind))for(var line:WarehouseJson.maps(row.get("lines")))assertAggregate("charges",records.get("charges",WarehouseJson.text(line,"id"),false));}
    private static List<?> array(Object value){return value instanceof List<?> l?l:List.of();}
    @Transactional public Map<String,Object> manualCharge(Map<String,Object> input){
        rules.permission("edit");FinanceInput.keys(input,"requestId","client","warehouse","description","type","invoiceType","amount","currency");String request=FinanceInput.id(input,"requestId"),clientId=FinanceInput.id(input,"client");var client=records.scoped("clients",clientId,true);
        String warehouse=FinanceInput.text(input,"warehouse",64,false);if(!warehouse.isEmpty())records.scoped("warehouses",warehouse,true);
        String hash=FinanceInput.hash(input);var replay=claim(request,"FINANCE_MANUAL_CHARGE",hash);if(replay!=null){assertAggregate("charges",replay);return replay;}
        var entry=new LinkedHashMap<String,Object>();entry.put("description",FinanceInput.text(input,"description",500,true));entry.put("amount",FinanceInput.money(FinanceInput.number(input.get("amount"),"amount",false)));entry.put("type",FinanceInput.option(input,"type","Additional","Additional","Picking","Storage","Goods In","Collection","Rework"));
        entry.put("warehouse",warehouse);String currency=currency(client);if(input.containsKey("currency")&&!currency.equals(input.get("currency")))throw WarehouseException.invalid("Charge currency must match client");entry.put("currency",currency);
        String typeId=FinanceInput.text(input,"invoiceType",64,false);if(!typeId.isEmpty()){var type=records.get("invoiceTypes",typeId,true);if(!WarehouseJson.enabled(type.get("active")))throw WarehouseException.invalid("Invoice type is inactive");entry.put("type",type.get("chargeType"));entry.put("vatRate",type.get("vatRate"));entry.put("invoiceType",typeId);}
        entry.put("source","manual:"+scope.actor()+":"+request);var saved=post(clientId,entry,Map.of("kind","manual","input",input));return complete(request,hash,saved);
    }
    @Transactional public Map<String,Object> draft(Map<String,Object> input){
        rules.permission("edit");FinanceInput.keys(input,"requestId","client","chargeIds","name","notes");String request=FinanceInput.id(input,"requestId"),clientId=FinanceInput.id(input,"client");var client=records.scoped("clients",clientId,true);String hash=FinanceInput.hash(input);var replay=claim(request,"FINANCE_INVOICE_DRAFT",hash);if(replay!=null){assertAggregate("invoices",replay);return replay;}
        if(!(input.get("chargeIds") instanceof List<?> ids)||ids.isEmpty()||ids.size()>500)throw WarehouseException.invalid("Select 1 to 500 charges");var selected=new TreeSet<String>();for(Object id:ids){if(!(id instanceof String s)||s.isBlank()||s.length()>64||!selected.add(s))throw WarehouseException.invalid("Charge identities must be unique");}
        var lines=new ArrayList<Map<String,Object>>();var charges=new ArrayList<Map<String,Object>>();BigDecimal net=BigDecimal.ZERO,tax=BigDecimal.ZERO;String currency=null;
        for(String cid:selected){var charge=records.get("charges",cid,true);AdjustmentSupport.unlocked(jdbc,cid,"");assertAggregate("charges",charge);String chargeCurrency=FinanceInput.option(charge,"currency",currency(client),"GBP","USD","EUR","CNY");if(currency==null)currency=chargeCurrency;if(!clientId.equals(charge.get("client"))||!"UNCONFIRMED".equals(charge.get("status"))||!currency.equals(chargeCurrency))throw WarehouseException.conflict("Charge client, currency or status changed");
            BigDecimal amount=FinanceInput.money(charge.getOrDefault("billableAmount",charge.get("amount"))),rate=WarehouseJson.enabled(client.get("vatExempt"))?BigDecimal.ZERO:FinanceInput.number(WarehouseJson.empty(charge.get("vatRate"))?(WarehouseJson.empty(client.get("serviceVatRate"))?0:client.get("serviceVatRate")):charge.get("vatRate"),"vatRate",false);if(rate.compareTo(new BigDecimal("100"))>0)throw WarehouseException.invalid("VAT must be at most 100%");
            BigDecimal lineTax=amount.multiply(rate).movePointLeft(2).setScale(2,RoundingMode.HALF_EVEN);var line=new LinkedHashMap<String,Object>();line.put("id",cid);line.put("description",charge.get("description"));line.put("amount",amount);line.put("vatRate",rate);line.put("tax",lineTax);lines.add(line);charges.add(charge);net=net.add(amount);tax=tax.add(lineTax);
        }
        String id=UUID.randomUUID().toString();var data=new LinkedHashMap<String,Object>();data.put("client",clientId);data.put("reference","INV-"+id);data.put("name",FinanceInput.text(input,"name",200,false));data.put("notes",FinanceInput.text(input,"notes",5000,false));data.put("status","DRAFT");data.put("currency",currency);data.put("lines",lines);data.put("net",net);data.put("tax",tax);data.put("amount",net.add(tax));
        var saved=records.write("invoices",id,data,null,"invoice:"+id,clientId);var refs=new LinkedHashMap<String,String>();refs.put("client",clientId);int referenceIndex=0;
        for(int lineIndex=0;lineIndex<charges.size();lineIndex++){
            var charge=charges.get(lineIndex);String cid=WarehouseJson.text(charge,"id");
            jdbc.update("INSERT INTO wh_finance_invoice_claim(charge_id,invoice_id) VALUES(?,?)",cid,id);
            var line=lines.get(lineIndex);
            jdbc.update("INSERT INTO wh_finance_invoice_line(invoice_id,charge_id,snapshot_json) VALUES(?,?,?)",id,cid,WarehouseJson.write(Map.of("line",line,"charge",charge)));
            refs.put("charge"+referenceIndex++,cid);
            // Graph references may outnumber invoice lines; their counter is independent.
            String warehouse=WarehouseJson.text(charge,"warehouse");if(!warehouse.isEmpty())refs.put("warehouse"+referenceIndex++,warehouse);
            for(Object wid:array(charge.get("warehouseIds")))refs.put("warehouse"+referenceIndex++,String.valueOf(wid));
            for(Object oid:array(charge.get("orderIds"))){var order=records.scoped("orders",String.valueOf(oid),false);refs.put("order"+referenceIndex++,WarehouseJson.text(order,"id"));}
            var changed=FinanceInput.business(charge);changed.put("status","INVOICED");changed.put("invoice",id);writeExisting("charges",charge,changed);
        }
        records.replaceReferences(id,refs);records.audit("CREATE_DRAFT_INVOICE","invoices",id,null,saved);return complete(request,hash,saved);
    }
    @Transactional public Map<String,Object> invoiceAction(String id,Map<String,Object> input){
        rules.permission("edit");FinanceInput.keys(input,"requestId","action","_version");String request=FinanceInput.id(input,"requestId"),action=FinanceInput.option(input,"action","","confirm","unconfirm");var existing=records.get("invoices",id,false);assertAggregate("invoices",existing);records.scoped("clients",WarehouseJson.text(existing,"client"),true);
        String hash=FinanceInput.hash(Map.of("id",id,"input",input));var replay=claim(request,"FINANCE_INVOICE_ACTION",hash);if(replay!=null){assertAggregate("invoices",replay);return replay;}
        var old=records.get("invoices",id,true);if(((Number)old.get("_version")).longValue()!=WarehouseJson.integer(input.get("_version"),"_version",1,Long.MAX_VALUE))throw WarehouseException.conflict("Invoice changed");String status=WarehouseJson.text(old,"status");var data=FinanceInput.business(old);AdjustmentSupport.invoiceUnlocked(jdbc,old,"");
        if("confirm".equals(action)){if(!"DRAFT".equals(status))throw WarehouseException.conflict("Only draft invoices can be confirmed");data.put("status","CONFIRMED");data.put("confirmedAt",Instant.now().toString());}
        else{if(jdbc.queryForObject("SELECT COUNT(*) FROM wh_finance_credit_note WHERE invoice_id=?",Long.class,id)>0)throw WarehouseException.conflict("An invoice with credit notes cannot be unconfirmed / 已有贷项的账单不能撤销");if(!Set.of("DRAFT","CONFIRMED").contains(status))throw WarehouseException.conflict("Invoice already unconfirmed");var ids=WarehouseJson.maps(old.get("lines")).stream().map(l->WarehouseJson.text(l,"id")).sorted().toList();for(String cid:ids){var charge=records.get("charges",cid,true);assertAggregate("charges",charge);if(!id.equals(charge.get("invoice"))||!"INVOICED".equals(charge.get("status")))throw WarehouseException.conflict("Invoice charge ownership changed");if(jdbc.update("DELETE FROM wh_finance_invoice_claim WHERE charge_id=? AND invoice_id=?",cid,id)!=1)throw WarehouseException.conflict("Invoice claim changed");var changed=FinanceInput.business(charge);changed.put("status","UNCONFIRMED");changed.remove("invoice");writeExisting("charges",charge,changed);}data.put("status","UNCONFIRMED");data.put("unconfirmedAt",Instant.now().toString());}
        var result=writeExisting("invoices",old,data);records.audit("INVOICE_"+action.toUpperCase(Locale.ROOT),"invoices",id,old,result);return complete(request,hash,result);
    }
    private Map<String,Object> writeExisting(String kind,Map<String,Object> row,Map<String,Object> data){String id=WarehouseJson.text(row,"id");String natural=jdbc.queryForObject("SELECT natural_key FROM wh_record WHERE id=?",String.class,id);return records.write(kind,id,data,((Number)row.get("_version")).longValue(),natural,WarehouseJson.text(data,"client"));}
    @Transactional public Map<String,Object> preview(Map<String,Object> input){rules.permission("query");FinanceInput.keys(input,"client","mode","from","to");return quote(input);}
    @Transactional public Map<String,Object> commit(Map<String,Object> input){
        rules.permission("edit");FinanceInput.keys(input,"client","mode","from","to","requestId","quoteHash");String client=FinanceInput.id(input,"client"),request=FinanceInput.id(input,"requestId");records.scoped("clients",client,true);String hash=FinanceInput.hash(input);var replay=claim(request,"FINANCE_BILLING",hash);if(replay!=null){for(var charge:WarehouseJson.maps(replay.get("charges")))assertAggregate("charges",charge);return replay;}
        var args=new LinkedHashMap<>(input);args.remove("requestId");args.remove("quoteHash");var quote=quote(args);if(!Objects.equals(input.get("quoteHash"),quote.get("quoteHash")))throw WarehouseException.conflict("Billing preview changed; preview again");var entries=WarehouseJson.maps(quote.get("entries"));if(entries.isEmpty())throw WarehouseException.conflict("No new charges in this period");var charges=new ArrayList<Map<String,Object>>();
        for(var entry:entries){var charge=post(client,entry,Map.of("quoteHash",quote.get("quoteHash"),"client",client,"mode",quote.get("mode"),"from",quote.get("from"),"to",quote.get("to"),"entry",entry));charges.add(charge);if(entry.containsKey("periodId")){String pid=WarehouseJson.text(entry,"periodId");jdbc.update("UPDATE wh_finance_period SET settled_count=?,settled_amount=? WHERE id=?",entry.get("orderCount"),entry.get("cumulativeAmount"),pid);for(Object oid:array(entry.get("orderIds"))){var order=records.scoped("orders",String.valueOf(oid),true);var data=FinanceInput.business(order);data.put("billingStatus","CHARGED");data.put("tierChargeId",charge.get("id"));writeExisting("orders",order,data);}}}
        var result=new LinkedHashMap<>(quote);result.put("status","COMPLETE");result.put("charges",charges);String runId=UUID.randomUUID().toString();var saved=records.write("billingRuns",runId,result,null,"billing-run:"+runId,client);var refs=new LinkedHashMap<String,String>();refs.put("client",client);int index=0;for(var charge:charges){refs.put("charge"+index++,WarehouseJson.text(charge,"id"));for(Object wid:array(charge.get("warehouseIds")))refs.put("warehouse"+index++,String.valueOf(wid));for(Object oid:array(charge.get("orderIds")))refs.put("order"+index++,String.valueOf(oid));}records.replaceReferences(runId,refs);records.audit("COMMIT_BILLING","billingRuns",runId,null,saved);return complete(request,hash,saved);
    }
    private Map<String,Object> quote(Map<String,Object> input){
        String clientId=FinanceInput.id(input,"client"),mode=FinanceInput.text(input,"mode",20,true);if(!Set.of("Recurring","OrderTier","Storage").contains(mode))throw WarehouseException.invalid("Unsupported billing mode");
        LocalDate from=FinanceInput.date(input,"from"),to=FinanceInput.date(input,"to");if(from.isAfter(to)||!to.isBefore(LocalDate.now(ZoneOffset.UTC))||java.time.temporal.ChronoUnit.DAYS.between(from,to)>366)throw WarehouseException.invalid("Select at most 366 days of completed UTC billing periods");var client=records.scoped("clients",clientId,true);var entries=new ArrayList<Map<String,Object>>();int candidates=0;
        if("Storage".equals(mode)){entries.addAll(new StorageHistoryService(records,scope,rules).entries(clientId,from,to));}else if("Recurring".equals(mode)){
            var all=records.clientRecordsCurrent("recurring",clientId);if(all.size()>1000)throw WarehouseException.invalid("Too many recurring rules for one run");for(var rule:all){scope.assertRecord("recurring",rule);if(!WarehouseJson.enabled(rule.get("active")))continue;String frequency=FinanceInput.option(rule,"frequency","Daily","Daily","Weekly","Monthly");LocalDate cursor=from;
                while(!cursor.isAfter(to)){if(++candidates>2000)throw WarehouseException.invalid("Limit billing run to 2000 candidate periods");var range=BillingPeriods.period(cursor.toString(),frequency);if(LocalDate.parse(range.get("from")).isBefore(from)||LocalDate.parse(range.get("to")).isAfter(to))throw WarehouseException.invalid("Select whole "+frequency+" periods");String source="recurring:"+rule.get("id")+":"+range.get("from")+":"+range.get("to");if(!posted(source)){var e=new LinkedHashMap<String,Object>();e.put("source",source);e.put("description",rule.get("description")+" "+range.get("from")+" - "+range.get("to"));e.put("amount",BillingCalculator.recurringAmount(rule));e.put("type",rule.getOrDefault("type","Additional"));e.put("warehouse",rule.getOrDefault("warehouse",""));e.put("ruleId",rule.get("id"));e.put("ruleSnapshot",rule);e.put("currency",currency(client));entries.add(e);}if(entries.size()>2000)throw WarehouseException.invalid("Limit billing run to 2000 entries");cursor=LocalDate.parse(range.get("to")).plusDays(1);}
            }
        }else{
            var periods=jdbc.queryForList("SELECT * FROM wh_finance_period WHERE client_id=? AND from_date<=? AND to_date>=? ORDER BY id FOR UPDATE",clientId,to.toString(),from.toString());
            for(var p:periods){if(LocalDate.parse(p.get("from_date").toString()).isBefore(from)||LocalDate.parse(p.get("to_date").toString()).isAfter(to))throw WarehouseException.invalid("Select whole order tier periods");String pid=String.valueOf(p.get("id"));var orderIds=jdbc.queryForList("SELECT order_id FROM wh_finance_tier_order WHERE period_id=? ORDER BY order_id FOR UPDATE",String.class,pid);if(orderIds.size()>20000)throw WarehouseException.invalid("Period exceeds 20000 orders");for(String oid:orderIds){var order=records.scoped("orders",oid,true);if(!clientId.equals(order.get("client"))||!"DESPATCHED".equals(order.get("status")))throw WarehouseException.conflict("Tier order evidence changed");}
                long settled=((Number)p.get("settled_count")).longValue();if(settled==orderIds.size())continue;if(settled>orderIds.size())throw WarehouseException.conflict("Tier membership regressed");var snapshot=WarehouseJson.map(String.valueOf(p.get("snapshot_json")));var rule=WarehouseJson.map(WarehouseJson.write(snapshot.get("rule")));var q=BillingCalculator.orderTierAdjustment(orderIds.size(),rule,List.of(p.get("settled_amount")));var e=new LinkedHashMap<String,Object>(q);e.put("periodId",pid);e.put("orderIds",orderIds);e.put("source","ordertier:"+pid+":"+orderIds.size());e.put("description","Order tier: "+orderIds.size()+" orders "+p.get("from_date")+" - "+p.get("to_date"));e.put("type","Picking");e.put("currency",p.get("currency"));entries.add(e);
            }
        }
        if(entries.stream().map(e->e.get("currency")).distinct().count()>1)throw WarehouseException.conflict("Select periods using one currency / 请按同一币种分别结算");
        var quote=new LinkedHashMap<String,Object>(input);quote.put("entries",entries);quote.put("amount",entries.stream().map(e->FinanceInput.money(e.get("amount"))).reduce(BigDecimal.ZERO,BigDecimal::add));if(WarehouseJson.write(quote).length()>2000000)throw WarehouseException.invalid("Billing preview exceeds resource limit; split the period");quote.put("quoteHash",FinanceInput.hash(quote));return quote;
    }
    private boolean posted(String source){return jdbc.queryForObject("SELECT COUNT(*) FROM wh_finance_source WHERE source_key=?",Long.class,source)>0;}
    private Map<String,Object> post(String client,Map<String,Object> entry,Map<String,Object> evidence){
        String id=UUID.randomUUID().toString(),source=WarehouseJson.text(entry,"source");var data=new LinkedHashMap<>(entry);data.remove("ruleSnapshot");data.remove("storageContext");data.put("client",client);data.put("status","UNCONFIRMED");data.put("amount",FinanceInput.money(entry.get("amount")));var saved=records.write("charges",id,data,null,source,client);
        jdbc.update("INSERT INTO wh_finance_source(source_key,charge_id,evidence_json) VALUES(?,?,?)",source,id,WarehouseJson.write(evidence));var refs=new LinkedHashMap<String,String>();refs.put("client",client);for(String[] ref:List.of(new String[]{"warehouse","warehouse"},new String[]{"ruleId","rule"},new String[]{"invoiceType","invoiceType"})){String value=WarehouseJson.text(data,ref[0]);if(!value.isEmpty())refs.put(ref[1],value);}int n=0;for(Object wid:array(data.get("warehouseIds")))refs.put("storageWarehouse"+n++,String.valueOf(wid));for(Object day:array(data.get("storageDays")))jdbc.update("INSERT INTO wh_storage_billed_day(client_id,billing_day,charge_id) VALUES(?,?,?)",client,String.valueOf(day),id);for(Object order:array(data.get("orderIds")))refs.put("order"+n++,String.valueOf(order));records.replaceReferences(id,refs);if(entry.get("storageContext") instanceof Map<?,?>)new StorageIdentityReviewService(records,scope,rules).consume(AdjustmentSupport.map(entry.get("storageContext")),id);records.audit("POST_FINANCE_CHARGE","charges",id,null,saved);return saved;
    }
    private Map<String,Object> claim(String request,String type,String hash){jdbc.update("INSERT INTO wh_operation_request(actor_id,request_id,operation_type,request_hash,response_json) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE request_id=request_id",scope.actor(),request,type,hash,"{}");return jdbc.queryForObject("SELECT operation_type,request_hash,response_json FROM wh_operation_request WHERE actor_id=? AND request_id=? FOR UPDATE",(rs,n)->{if(!type.equals(rs.getString(1))||!hash.equals(rs.getString(2)))throw WarehouseException.conflict("Request identity already used");var response=WarehouseJson.map(rs.getString(3));return response.isEmpty()?null:response;},scope.actor(),request);}
    private Map<String,Object> complete(String request,String hash,Map<String,Object> response){if(jdbc.update("UPDATE wh_operation_request SET response_json=? WHERE actor_id=? AND request_id=? AND request_hash=?",WarehouseJson.write(response),scope.actor(),request,hash)!=1)throw WarehouseException.conflict("Request journal changed");return response;}
    private static String currency(Map<String,Object> client){return WarehouseJson.empty(client.get("currency"))?"GBP":FinanceInput.option(client,"currency","GBP","GBP","USD","EUR","CNY");}
}
